import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Install and connect","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/distant-horizons-support-pumpkin/docs/setup.md"},"headers":[],"relativePath":"packages/distant-horizons-support-pumpkin/docs/setup.md","filePath":"packages/distant-horizons-support-pumpkin/docs/setup.md","lastUpdated":1792252144000}`),a={name:`packages/distant-horizons-support-pumpkin/docs/setup.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="install-and-connect" tabindex="-1">Install and connect <a class="header-anchor" href="#install-and-connect" aria-label="Permalink to “Install and connect”">​</a></h1><h2 id="check-client-compatibility" tabindex="-1">Check client compatibility <a class="header-anchor" href="#check-client-compatibility" aria-label="Permalink to “Check client compatibility”">​</a></h2><p>Before you install the server plugin, check its README for the supported Distant Horizons release and protocol. Install the Distant Horizons mod on each Java Edition client that will connect; Bedrock players can&#39;t establish Distant Horizons sessions.</p><h2 id="install-the-server-plugin" tabindex="-1">Install the server plugin <a class="header-anchor" href="#install-the-server-plugin" aria-label="Permalink to “Install the server plugin”">​</a></h2><ol><li>Download the latest Distant Horizons Support release.</li><li>Copy <code>distant-horizons-support-pumpkin.wasm</code> into the Pumpkin server&#39;s <code>plugins/</code> folder.</li><li>Start or restart the server. On first load, the plugin requests the data-folder permissions listed in its README. Approve the request in the server console; hot reload can&#39;t display this prompt.</li><li>Connect with a compatible Java client. On first load, the plugin creates its settings file in its data folder.</li></ol><p>The plugin README lists the available options, their defaults, and an example configuration. Settings changes take effect after a server restart. Distant Horizons Support can serve terrain from chunks Pumpkin has loaded, along with terrain it captured earlier and cached. It can&#39;t load or generate distant chunks: the shared provider interfaces exist, but Pumpkin&#39;s current adapter marks both operations as unavailable.</p><p>The server negotiates generation and sync request limits separately, and acknowledges client configuration updates. A nonzero client bandwidth setting limits outgoing transfers from the server. Its credit bucket can hold up to one full DH fragment message; zero means unlimited.</p><p>After connecting, use the plugin&#39;s status and cache commands to check which clients are connected and how much cache is in use.</p><p>PumpkinPIE is optional. Distant Horizons Support loads without it and reconnects automatically if PumpkinPIE becomes available later. The <code>dhs</code> expansion gives PumpkinPIE consumers access to session and cache values, without adding a required host plugin dependency. See the <a href="./placeholders">placeholder reference</a> for identifiers, values, and retry behavior.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};